@msig trait EquipmentAssessment_acquisition_process_equipment_assessment_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_equipment_assessment)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_equipment_assessment)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_equipment_assessment)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_equipment_assessment)
  }

  /** helper function to set the values of all input ports.
   * @param equipment_observation payload for data port equipment_observation
   */
  def put_concrete_inputs(equipment_observation : EIT_Acquisition_Supervisor.EquipmentObservation.Type): Unit = {
    put_equipment_observation(equipment_observation)
  }


  /** helper function to check EquipmentAssessment_acquisition_process_equipment_assessment's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param equipment_facts method that will be called with the value of the outgoing data
   *        port 'equipment_facts'.
   */
  def check_concrete_output(equipment_facts: EIT_Acquisition_Supervisor.EquipmentFacts.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val equipment_factsValue: EIT_Acquisition_Supervisor.EquipmentFacts.Type = get_equipment_facts().get
    if(!equipment_facts(equipment_factsValue)) {
      testFailures = testFailures :+ st"'equipment_facts' did not match expected: value of the outgoing data port is ${equipment_factsValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_equipment_observation(value : EIT_Acquisition_Supervisor.EquipmentObservation.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_equipment_assessment.operational_api.equipment_observation_Id, EIT_Acquisition_Supervisor.EquipmentObservation_Payload(value))
  }

  // getter for out DataPort
  def get_equipment_facts(): Option[EIT_Acquisition_Supervisor.EquipmentFacts.Type] = {
    val value: Option[EIT_Acquisition_Supervisor.EquipmentFacts.Type] = get_equipment_facts_payload() match {
      case Some(EIT_Acquisition_Supervisor.EquipmentFacts_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port equipment_facts.  Expecting 'EIT_Acquisition_Supervisor.EquipmentFacts_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Supervisor.EquipmentFacts.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_equipment_facts_payload(): Option[EIT_Acquisition_Supervisor.EquipmentFacts_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_equipment_assessment.initialization_api.equipment_facts_Id).asInstanceOf[Option[EIT_Acquisition_Supervisor.EquipmentFacts_Payload]]
  }

}
